def validate_model():
 ids={r[0] for r in REQ};cases={t[0] for t in TESTS};used=set()
 assert len(REQ)==len(ids)==35
 assert len(ENTITIES)==9 and len(FK)==12 and len(TESTS)==25
 assert len(LEAVES)==15 and len({x[0] for x in LEAVES})==15
 assert len(FUNCTIONS)==5 and len(COMPONENTS)==6 and len(MODULES)==11
 assert {leaf.split(' ')[0] for _,_,leaves in FUNCTIONS for leaf in leaves}=={x[0] for x in LEAVES}
 declared_modules={m[0]:m[2] for m in MODULES}
 for component,_,_,_,modules,_ in COMPONENTS:
  for module in modules.split(', '):assert declared_modules[module]==component,(component,module)
 assert {m[2] for m in MODULES}=={c[0] for c in COMPONENTS}
 for r in REQ:
  links=set(r[5].split(', '));assert links<=cases,(r[0],links-cases);used|=links
 assert used==cases,cases-used
 for a,f,b,p in FK:
  fields={e[0]:{x[0] for x in e[2]} for e in ENTITIES}
  assert f in fields[a] and p in fields[b]
 return {'domain_entities':8,'service_entities':1,'foreign_keys':12,'requirements':35,'tests':25,'functions':5,'components':6,'modules':11,'software_acceptance_tests_run':False}
